use config::Config;
use facts::FnFacts;
use report::{Diagnostic, Report, Summary};
use std::borrow::Cow;
use std::collections::BTreeMap;
use suppress::Suppression;

fn rule_diagnostics(f: &FnFacts, effects: &[rules::Effect], cfg: &Config) -> Vec<Diagnostic> {
    let source_lines = lines::code_lines(&f.source);
    [
        rules::fn_length_with_lines(f, cfg, source_lines),
        rules::fn_params(f, cfg),
        strict_style::fn_spacing(f, cfg),
        rules::complexity(f, cfg),
        rules::mutation_budget(f, &cfg.mutation_budget),
        rules::side_effect_density_with_lines(f, effects, cfg, || source_lines),
        strict_style::guard_clause(f, cfg),
    ]
    .concat()
}

fn invalid_suppression(f: &FnFacts, message: &str) -> Diagnostic {
    Diagnostic {
        path: f.path.clone(),
        line: f.line,
        column: f.column,
        rule_id: "invalid_suppression".into(),
        message: format!("function `{}`: {message}", f.name),
        actual: 1,
        limit: 0,
        details: vec![],
        source: f.whole_lines(),
    }
}

fn function_diagnostics(
    f: &FnFacts,
    effects: &[rules::Effect],
    cfg: &Config,
    across_the_run: Vec<Diagnostic>,
) -> (Vec<Diagnostic>, Suppression) {
    let mut out = rule_diagnostics(f, effects, cfg);
    out.extend(across_the_run);

    let suppression = suppress::parse(&f.preceding_line);
    match &suppression {
        Suppression::None => {}
        Suppression::Allow(rules) => out.retain(|d| !rules.contains(&d.rule_id)),
        Suppression::Invalid(message) => out.push(invalid_suppression(f, message)),
    }
    (out, suppression)
}

fn effect_counts<'a>(effects: impl Iterator<Item = &'a rules::Effect>) -> BTreeMap<String, usize> {
    let mut counts = BTreeMap::new();
    for effect in effects {
        *counts.entry(effect.kind.name().to_string()).or_default() += 1;
    }
    counts
}

fn summarize(
    facts: &[FnFacts],
    effects: &[Vec<rules::Effect>],
    policies: &[Cow<Config>],
    violations: usize,
) -> Summary {
    let (density_sum, max_density_milli) = facts
        .iter()
        .zip(effects)
        .zip(policies)
        .map(|((f, e), policy)| rules::density_milli(f, e, policy))
        .fold((0u128, 0), |(sum, maximum), density| {
            (sum + density as u128, maximum.max(density))
        });
    let measured = facts
        .iter()
        .filter(|fact| fact.complexity.is_some())
        .count();
    Summary {
        functions: facts.len(),
        violations,
        complexity_measured: measured,
        complexity_unavailable: facts.len() - measured,
        mean_density_milli: (density_sum / facts.len().max(1) as u128) as usize,
        density_sum_milli: usize::try_from(density_sum).ok(),
        max_density_milli,
        effect_counts: effect_counts(effects.iter().flatten()),
    }
}

/// Observed effects and existing suppression boundaries for a borrowed graph owner.
pub trait EffectSource: graph::EffectInput {
    fn direct_effects(&self, config: &Config) -> Vec<rules::Effect>;
    fn effect_boundary(&self) -> bool;
}

impl<F: std::borrow::Borrow<FnFacts>> EffectSource for F {
    fn direct_effects(&self, config: &Config) -> Vec<rules::Effect> {
        rules::effects_of(self.borrow(), config)
    }
    fn effect_boundary(&self) -> bool {
        graph::is_boundary(self.borrow())
    }
}

/// Direct effects of every function plus what it inherits through the call graph.
pub fn all_effects<F: EffectSource>(
    facts: &[F],
    graph: &graph::Graph,
    cfg: &Config,
) -> Vec<Vec<rules::Effect>> {
    let mut direct: Vec<_> = facts.iter().map(|f| f.direct_effects(cfg)).collect();
    graph.add_open_calls(&mut direct);

    let boundary: Vec<_> = facts.iter().map(EffectSource::effect_boundary).collect();
    let inputs = graph::Inputs {
        facts,
        graph,
        direct: &direct,
        boundary: &boundary,
    };
    graph::propagate(&inputs, cfg.side_effects.transitive_depth)
}

/// Evaluates all rules. Input order does not matter: facts are merged first.
pub fn evaluate(facts: Vec<FnFacts>, cfg: &Config) -> Result<Report, String> {
    evaluate_and_retain(facts, cfg).map(|(report, _)| report)
}

/// Return the merged, path-selected observations for another consumer without copying bodies.
pub fn evaluate_and_retain(
    facts: Vec<FnFacts>,
    cfg: &Config,
) -> Result<(Report, Vec<FnFacts>), String> {
    evaluate_inputs(facts, cfg, Retention::Report, None)
        .map(|evaluation| (evaluation.report, evaluation.facts))
}

/// Completed diagnostic ownership follows report sorting without location-based inference.
pub struct Evaluation {
    pub report: Report,
    pub facts: Vec<FnFacts>,
    /// One index into `facts` for each diagnostic in `report`.
    pub diagnostic_owners: Vec<usize>,
    /// Explicit consumers may retain completed suppression scopes and excluded observations.
    pub scopes: Option<Scopes>,
    /// Opt-in completed effects, keyed by the original selected owner ID.
    pub effects: Option<BTreeMap<String, Vec<rules::Effect>>>,
}

#[derive(Default)]
pub struct Scopes {
    /// Aligned with the selected facts, from their completed rule evaluation.
    pub suppressions: Vec<Suppression>,
    pub excluded: Vec<FnFacts>,
}

#[derive(Clone, Copy)]
pub enum Retention {
    Report,
    Owners,
    Scopes,
}

pub fn evaluate_with_owners(facts: Vec<FnFacts>, cfg: &Config) -> Result<Evaluation, String> {
    evaluate_inputs(facts, cfg, Retention::Owners, None)
}

/// Retain completed numeric scope outcomes without evaluating a rule or parsing a comment again.
pub fn evaluate_with_scopes(facts: Vec<FnFacts>, cfg: &Config) -> Result<Evaluation, String> {
    evaluate_inputs(facts, cfg, Retention::Scopes, None)
}

/// Evaluate with only the requested run-local metadata retained.
pub fn evaluate_retained(
    facts: Vec<FnFacts>,
    cfg: &Config,
    retention: Retention,
) -> Result<Evaluation, String> {
    evaluate_inputs(facts, cfg, retention, None)
}

/// Consume completed effects from the same policy and scoped owners; missing results are errors.
/// The consumer resolves cross-unit targets; core still owns propagation and rule policy.
pub fn evaluate_with_effects(
    facts: Vec<FnFacts>,
    cfg: &Config,
    retention: Retention,
    effects: BTreeMap<String, Vec<rules::Effect>>,
) -> Result<Evaluation, String> {
    evaluate_inputs(facts, cfg, retention, Some(effects))
}

/// Retain the effects already used for diagnostics, moving their vectors without reevaluation.
/// Supplied effects must belong to these scoped owners and the same configuration, as in
/// `evaluate_with_effects`. Retention of effects is independent of diagnostic scope metadata.
pub fn evaluate_retaining_effects(
    facts: Vec<FnFacts>,
    cfg: &Config,
    retention: Retention,
    completed: Option<BTreeMap<String, Vec<rules::Effect>>>,
) -> Result<Evaluation, String> {
    evaluate_observations(
        EvaluationInputs {
            facts,
            retention,
            completed,
            retain_effects: true,
        },
        cfg,
    )
}

/// Selected compiler observations and completed effects for consumers that do not request rules.
pub struct EffectObservations {
    pub facts: Vec<FnFacts>,
    pub effects: BTreeMap<String, Vec<rules::Effect>>,
}

/// Reuse observation ordering, merging and path exclusions without evaluating effects or rules.
pub fn selected_observations(facts: Vec<FnFacts>, cfg: &Config) -> Result<Vec<FnFacts>, String> {
    select_facts(facts, cfg, &mut None)
}

/// Reuse the evaluator's merge, exclusion and propagation steps without numeric diagnostics.
/// Supplied effects have the same owner/configuration contract as `evaluate_with_effects`.
pub fn effect_observations(
    facts: Vec<FnFacts>,
    cfg: &Config,
    completed: Option<BTreeMap<String, Vec<rules::Effect>>>,
) -> Result<EffectObservations, String> {
    let facts = selected_observations(facts, cfg)?;
    let effects = match completed {
        Some(completed) => take_completed_effects(&facts, completed)?,
        None => all_effects(&facts, &graph::build(&facts), cfg),
    };
    Ok(EffectObservations {
        effects: own_effects(&facts, effects),
        facts,
    })
}

fn own_effects(
    facts: &[FnFacts],
    effects: Vec<Vec<rules::Effect>>,
) -> BTreeMap<String, Vec<rules::Effect>> {
    facts
        .iter()
        .zip(effects)
        .map(|(fact, effects)| (fact.id.clone(), effects))
        .collect()
}

struct EvaluationInputs {
    facts: Vec<FnFacts>,
    retention: Retention,
    completed: Option<BTreeMap<String, Vec<rules::Effect>>>,
    retain_effects: bool,
}

struct RuleInputs<'a> {
    facts: &'a [FnFacts],
    effects: &'a [Vec<rules::Effect>],
    /// Read for rules across the whole run.
    cfg: &'a Config,
    /// One per fact: the run's config with its path's overrides merged in.
    policies: &'a [Cow<'a, Config>],
}

fn evaluated_diagnostics(
    inputs: RuleInputs<'_>,
    retention: Retention,
    scopes: &mut Option<Scopes>,
) -> (Vec<usize>, Vec<Diagnostic>) {
    if matches!(retention, Retention::Report) {
        let mut diagnostics = collect_diagnostics(inputs, |_, diagnostic| diagnostic, None);
        report::sort(&mut diagnostics);
        return (Vec::new(), diagnostics);
    }
    let mut owned = collect_diagnostics(
        inputs,
        |owner, diagnostic| (owner, diagnostic),
        scopes.as_mut().map(|scopes| &mut scopes.suppressions),
    );
    owned.sort_by(|(_, a), (_, b)| report::ordering(a, b));
    owned.into_iter().unzip()
}

fn collect_diagnostics<T>(
    inputs: RuleInputs<'_>,
    emit: impl Fn(usize, Diagnostic) -> T,
    mut scopes: Option<&mut Vec<Suppression>>,
) -> Vec<T> {
    let across_the_run = strict_style::across_the_run(inputs.facts, inputs.cfg);
    inputs
        .facts
        .iter()
        .zip(inputs.effects)
        .zip(inputs.policies)
        .zip(across_the_run)
        .enumerate()
        .flat_map(|(owner, (((f, e), policy), across_the_run))| {
            let emit = &emit;
            let (diagnostics, suppression) = function_diagnostics(f, e, policy, across_the_run);
            if let Some(scopes) = scopes.as_mut() {
                scopes.push(suppression);
            }
            diagnostics
                .into_iter()
                .map(move |diagnostic| emit(owner, diagnostic))
        })
        .collect()
}

fn evaluate_inputs(
    facts: Vec<FnFacts>,
    cfg: &Config,
    retention: Retention,
    completed: Option<BTreeMap<String, Vec<rules::Effect>>>,
) -> Result<Evaluation, String> {
    evaluate_observations(
        EvaluationInputs {
            facts,
            retention,
            completed,
            retain_effects: false,
        },
        cfg,
    )
}

fn evaluate_observations(inputs: EvaluationInputs, cfg: &Config) -> Result<Evaluation, String> {
    let EvaluationInputs {
        facts,
        retention,
        completed,
        retain_effects,
    } = inputs;
    let mut scopes = matches!(retention, Retention::Scopes).then(Scopes::default);
    let facts = select_facts(facts, cfg, &mut scopes)?;
    let graph = graph::build(&facts);
    let effects = completed_effects(&facts, &graph, cfg, completed)?;
    let policies: Vec<_> = facts.iter().map(|f| cfg.for_path(&f.path)).collect();

    let (diagnostic_owners, diagnostics) = evaluated_diagnostics(
        RuleInputs {
            facts: &facts,
            effects: &effects,
            cfg,
            policies: &policies,
        },
        retention,
        &mut scopes,
    );
    let summary = summarize(&facts, &effects, &policies, diagnostics.len());
    let fix_groups = groups::build(&facts, &graph, &diagnostics, cfg);
    let functions = complexity_report::findings(&facts, &diagnostics);
    let effects = retain_effects.then(|| own_effects(&facts, effects));
    Ok(Evaluation {
        report: Report {
            diagnostics,
            summary,
            fix_groups,
            functions,
        },
        facts,
        diagnostic_owners,
        scopes,
        effects,
    })
}

fn select_facts(
    facts: Vec<FnFacts>,
    cfg: &Config,
    scopes: &mut Option<Scopes>,
) -> Result<Vec<FnFacts>, String> {
    let excluded = exclusions::Matcher::compile(&cfg.exclude.0)?;
    Ok(facts::merge(facts)
        .into_iter()
        .filter_map(|fact| {
            if excluded.is_excluded(std::path::Path::new(&fact.path)) {
                if let Some(scopes) = scopes.as_mut() {
                    scopes.excluded.push(fact);
                }
                None
            } else {
                Some(fact)
            }
        })
        .collect())
}

fn completed_effects(
    facts: &[FnFacts],
    graph: &graph::Graph,
    cfg: &Config,
    completed: Option<BTreeMap<String, Vec<rules::Effect>>>,
) -> Result<Vec<Vec<rules::Effect>>, String> {
    match completed {
        None => Ok(all_effects(facts, graph, cfg)),
        Some(completed) => take_completed_effects(facts, completed),
    }
}

fn take_completed_effects(
    facts: &[FnFacts],
    mut completed: BTreeMap<String, Vec<rules::Effect>>,
) -> Result<Vec<Vec<rules::Effect>>, String> {
    facts
        .iter()
        .map(|fact| {
            completed
                .remove(&fact.id)
                .ok_or_else(|| "Missing completed compiler effects".to_string())
        })
        .collect()
}

#[cfg(test)]
mod tests {
    mod completed_effects;
    use super::*;
    use facts::{MutationEvent, sample};

    fn four_params(name: &str) -> FnFacts {
        FnFacts {
            params: 5,
            ..sample(name)
        }
    }

    #[test]
    fn source_rules_preserve_independent_line_limits_across_nested_comments() {
        let mut facts = sample("source");
        facts.source = "fn source() {\n/* outer\n/* nested */\n*/\nvalue();\n}\n".into();
        facts.statements = 3;
        let effects = [rules::Effect {
            kind: facts::EffectKind::Io,
            label: "write".into(),
            line: 5,
            via: None,
        }];
        let mut config = Config::default();
        config.fn_length.max_lines = 2;
        config.side_effects.min_lines = 3;

        let (diagnostics, _) = function_diagnostics(&facts, &effects, &config, vec![]);
        assert_eq!(diagnostics.len(), 2);
        assert_eq!(diagnostics[0].rule_id, "fn_length");
        assert_eq!(diagnostics[0].actual, 3);
        assert_eq!(diagnostics[1].rule_id, "side_effect_density");
        assert_eq!(diagnostics[1].actual, 1000);
        config.side_effects.min_lines = 4;
        let (diagnostics, _) = function_diagnostics(&facts, &effects, &config, vec![]);
        assert_eq!(diagnostics.len(), 1);
        assert_eq!(diagnostics[0].rule_id, "fn_length");
    }

    #[test]
    fn default_evaluation_keeps_no_owner_roster_and_preserves_the_report() {
        let plain = evaluate_inputs(
            vec![four_params("original")],
            &Config::default(),
            Retention::Report,
            None,
        )
        .unwrap();
        let owned =
            evaluate_with_owners(vec![four_params("original")], &Config::default()).unwrap();
        assert!(plain.scopes.is_none());
        assert_eq!(
            plain.report.summary.density_sum_milli,
            Some(plain.report.summary.mean_density_milli)
        );
        assert!(owned.scopes.is_none());
        assert_eq!(plain.diagnostic_owners.capacity(), 0);
        assert_eq!(plain.report, owned.report);
        assert_eq!(owned.diagnostic_owners, vec![0]);
    }

    #[test]
    fn borrowed_completed_effects_preserve_reports_and_require_every_selected_owner() {
        let facts = four_params("owner");
        let buffer = facts.source.as_ptr();
        let config = Config::default();
        let borrowed = vec![&facts];
        let graph = graph::build_resolved(&borrowed, |_, _| Vec::new());
        let effects = all_effects(&borrowed, &graph, &config);
        let completed = BTreeMap::from([(facts.id.clone(), effects.into_iter().next().unwrap())]);
        let expected = evaluate(vec![facts.clone()], &config).unwrap();
        let evaluated =
            evaluate_with_effects(vec![facts], &config, Retention::Scopes, completed).unwrap();
        assert_eq!(evaluated.report, expected);
        assert_eq!(evaluated.facts[0].source.as_ptr(), buffer);
        assert!(
            evaluate_with_effects(
                vec![four_params("missing")],
                &config,
                Retention::Report,
                BTreeMap::new()
            )
            .is_err()
        );
    }

    #[test]
    fn completed_scopes_retain_suppressions_and_move_excluded_source_buffers() {
        let mut excluded = four_params("excluded");
        excluded.path = "generated/file.rs".into();
        let buffer = excluded.source.as_ptr();
        let mut allowed = four_params("allowed");
        allowed.preceding_line = "// rstyle-allow(fn_params): fixture".into();
        let config: Config = toml::from_str("exclude=['generated/**']").unwrap();
        let original = vec![excluded, allowed, four_params("reported")];
        let expected = evaluate(original.clone(), &config).unwrap();
        let evaluated = evaluate_with_scopes(original, &config).unwrap();
        assert_eq!(evaluated.report, expected);
        let scopes = evaluated.scopes.unwrap();
        assert_eq!(scopes.excluded.len(), 1);
        assert_eq!(scopes.excluded[0].source.as_ptr(), buffer);
        assert_eq!(scopes.suppressions.len(), evaluated.facts.len());
        for (fact, suppression) in evaluated.facts.iter().zip(&scopes.suppressions) {
            match fact.name.as_str() {
                "allowed" => assert_eq!(suppression, &Suppression::Allow(vec!["fn_params".into()])),
                "reported" => assert_eq!(suppression, &Suppression::None),
                other => panic!("unexpected selected owner: {other}"),
            }
        }
        assert_eq!(evaluated.report.diagnostics.len(), 1);
        assert_eq!(
            evaluated.facts[evaluated.diagnostic_owners[0]].name,
            "reported"
        );
    }

    #[test]
    fn completed_diagnostic_owners_survive_sorting_and_shared_source_positions() {
        let mut first = four_params("zeta");
        first.path = "same.rs".into();
        first.line = 3;
        first.column = 8;
        let mut second = four_params("alpha");
        second.path = "same.rs".into();
        second.line = 3;
        second.column = 2;
        let buffers = [first.source.as_ptr(), second.source.as_ptr()];
        let evaluated = evaluate_with_owners(vec![first, second], &Config::default()).unwrap();
        let associations: Vec<_> = evaluated
            .report
            .diagnostics
            .iter()
            .zip(&evaluated.diagnostic_owners)
            .map(|(diagnostic, owner)| {
                (
                    diagnostic.column,
                    diagnostic.rule_id.as_str(),
                    evaluated.facts[*owner].name.as_str(),
                )
            })
            .collect();
        assert_eq!(
            associations,
            vec![(2, "fn_params", "alpha"), (8, "fn_params", "zeta")]
        );
        assert!(
            evaluated
                .facts
                .iter()
                .all(|fact| buffers.contains(&fact.source.as_ptr()))
        );
    }

    #[test]
    fn suppression_removes_only_named_rule() {
        let mut f = four_params("f");
        f.preceding_line = "// rstyle-allow(fn_params): ffi shim".into();
        f.mutations = (1..=4)
            .map(|line| MutationEvent {
                origin: crate::facts::MutationOrigin::Source,
                root: "v".into(),
                field_path: String::new(),
                line,
                escapes: true,
                delegated: false,
            })
            .collect();
        let report = evaluate(vec![f], &Config::default()).unwrap();
        let ids: Vec<_> = report
            .diagnostics
            .iter()
            .map(|d| d.rule_id.as_str())
            .collect();
        assert_eq!(ids, ["mutation_per_target"]);
    }

    #[test]
    fn suppression_without_reason_is_reported() {
        let mut f = four_params("f");
        f.preceding_line = "// rstyle-allow(fn_params)".into();
        let report = evaluate(vec![f], &Config::default()).unwrap();
        let ids: Vec<_> = report
            .diagnostics
            .iter()
            .map(|d| d.rule_id.as_str())
            .collect();
        assert_eq!(ids, ["fn_params", "invalid_suppression"]);
    }

    #[test]
    fn output_is_independent_of_input_order() {
        let mut b = four_params("b");
        b.path = "src/b.rs".into();
        let one = evaluate(vec![four_params("a"), b.clone()], &Config::default()).unwrap();
        let two = evaluate(vec![b, four_params("a")], &Config::default()).unwrap();
        assert_eq!(one, two);
    }

    #[test]
    fn excluded_paths_are_dropped() {
        let mut f = four_params("f");
        f.path = "target/gen/x.rs".into();
        let report = evaluate(vec![f], &Config::default()).unwrap();
        assert_eq!(report.summary.functions, 0);
        assert!(report.diagnostics.is_empty());
    }

    #[test]
    fn retained_inputs_follow_policy_exclusions_without_copying_body_buffers() {
        let mut kept = four_params("kept");
        kept.pdg = Some(crate::pdgtest::emit_loop("Cow", "value"));
        let source = kept.source.as_ptr();
        let nodes = kept.pdg.as_ref().unwrap().nodes.as_ptr();
        let mut excluded = sample("excluded");
        excluded.path = "target/generated.rs".into();
        let (report, retained) =
            evaluate_and_retain(vec![excluded, kept], &Config::default()).unwrap();
        assert_eq!(report.summary.functions, 1);
        assert!(
            report
                .diagnostics
                .iter()
                .any(|row| row.rule_id == "fn_params")
        );
        assert_eq!(retained.len(), 1);
        assert_eq!(retained[0].source.as_ptr(), source);
        assert_eq!(retained[0].pdg.as_ref().unwrap().nodes.as_ptr(), nodes);
    }

    #[test]
    fn summary_math() {
        let mut heavy = sample("heavy");
        heavy.line = 5;
        heavy.statements = 4;
        heavy.calls = vec![facts::CallEvent {
            callee: "std::fs::write".into(),
            line: 6,
            dynamic: false,
            library: None,
            library_callee: None,
        }];
        let report = evaluate(vec![sample("pure"), heavy], &Config::default()).unwrap();
        assert_eq!(report.summary.functions, 2);
        assert_eq!(report.summary.max_density_milli, 750);
        assert_eq!(report.summary.mean_density_milli, 375);
        assert_eq!(report.summary.effect_counts["io"], 1);
    }

    #[test]
    fn overrides_apply_per_function_path() {
        let cfg = Config::parse(
            r#"
[[overrides]]
paths = ["**/adapters/**"]
fn_params = { max_params = 5 }
side_effects.weights = { io = 1 }
"#,
        )
        .unwrap();
        let writer = |path: &str| FnFacts {
            path: path.into(),
            source: format!("fn w() {{\n{}}}", "w();\n".repeat(10)),
            statements: 4,
            calls: vec![facts::CallEvent {
                callee: "std::fs::write".into(),
                line: 2,
                dynamic: false,
                library: None,
                library_callee: None,
            }],
            ..four_params(&path.replace('/', "_"))
        };
        let report = evaluate(
            vec![
                writer("src/adapters/store.rs"),
                writer("src/domain/rules.rs"),
            ],
            &cfg,
        )
        .unwrap();
        let rules: Vec<_> = report
            .diagnostics
            .iter()
            .map(|d| (d.path.as_str(), d.rule_id.as_str()))
            .collect();
        assert_eq!(
            rules,
            [
                ("src/domain/rules.rs", "fn_params"),
                ("src/domain/rules.rs", "side_effect_density"),
            ]
        );
    }
}

//! The report as Markdown, for a pull request's description. The rating comes first, with each
//! check that holds it above low and why. Two folds follow: a table of what changed at a glance,
//! and every changed function in a table per file. A check is one of the rules the rating is the
//! strongest reason of, so the headline is the worst check by construction.

use super::rating::{
    ADDED_CALL, ANALYSIS_UNAVAILABLE, Level, PDG_CHANGE, Reason, UNCLASSIFIED_CALL,
    UNRESOLVED_CALLS,
};
use super::{ChangeKind, ChangeReport, EffectChange, FunctionChange};
use sha2::{Digest, Sha256};
use std::collections::{BTreeMap, BTreeSet};

/// The rating's rules, in the order a reader should meet them, with the name each check goes by.
const CHECKS: [(&str, &str); 5] = [
    (PDG_CHANGE, "Changed code"),
    (ADDED_CALL, "Calls a rule names"),
    (UNCLASSIFIED_CALL, "Unclassified library calls"),
    (UNRESOLVED_CALLS, "Calls to unknown targets"),
    (ANALYSIS_UNAVAILABLE, "Changes outside functions"),
];

/// How many callees a check's line names, and how many unclassified calls the table lists.
const CALLEES_SHOWN: usize = 3;
const CALLS_SHOWN: usize = 10;

const KINDS: [ChangeKind; 5] = [
    ChangeKind::Changed,
    ChangeKind::Added,
    ChangeKind::Removed,
    ChangeKind::TextOnly,
    ChangeKind::Unknown,
];

impl ChangeReport {
    /// `pull_request_url` names the GitHub PR whose diff the report links to, such as
    /// `https://github.com/OWNER/REPO/pull/123`. Removed functions link to the base side;
    /// other functions link to the head side. Without a URL, paths and names stay plain text.
    pub fn markdown(&self, pull_request_url: Option<&str>) -> String {
        let links =
            Links(pull_request_url.map(|url| url.trim_end_matches('/').trim_end_matches("/files")));
        let risk = self.rating.risk;
        let headline = format!("### {} Merge risk: {}", icon(risk), risk.name());

        [
            Some(headline),
            Some(self.why()),
            Some(self.glance()),
            self.functions(&links),
        ]
        .into_iter()
        .flatten()
        .collect::<Vec<_>>()
        .join("\n\n")
    }

    /// Each check above low, with what it found. An unrated report says why nothing is rated.
    fn why(&self) -> String {
        if !self.rating.policy_configured {
            return "Not rated: the base's `rstyle.toml` has no `[risk]` rules.".to_owned();
        }
        let held: Vec<String> = CHECKS
            .into_iter()
            .filter_map(|(rule, title)| held(&self.rating.reasons, rule, title))
            .collect();

        match held.is_empty() {
            true => "Nothing holds it above low.".to_owned(),
            false => held.join("\n"),
        }
    }

    fn glance(&self) -> String {
        let rows = [
            ("Impact", self.impact()),
            ("Signatures", self.signatures()),
            ("Calls", self.calls()),
            ("Effects", self.effects()),
            ("Coverage", self.coverage()),
        ];
        let rows = rows.map(|(check, result)| format!("| **{check}** | {} |", cell(&result)));

        format!(
            "<details><summary><strong>At a glance</strong></summary>\n\n\
             | Check | Result |\n|---|---|\n{}\n\n</details>",
            rows.join("\n")
        )
    }

    fn files(&self) -> BTreeSet<&str> {
        self.changes
            .iter()
            .map(|change| change.path.as_str())
            .collect()
    }

    fn impact(&self) -> String {
        if self.changes.is_empty() {
            return "no function changed".to_owned();
        }
        let files = plural(self.files().len(), "file", "files");
        let functions = plural(self.changes.len(), "function", "functions");
        format!("{functions} in {files}: {}", tally(&self.changes))
    }

    /// Every changed function's signature is compared, a text-only or unknown one's too, so none
    /// changing is unchanged. What the comparison can't see is the coverage row's to say.
    fn signatures(&self) -> String {
        let changed = self
            .changes
            .iter()
            .filter(|change| change.signature_changed)
            .count();
        match changed {
            0 => "✅ unchanged".to_owned(),
            count => format!("👀 {count} changed"),
        }
    }

    /// What the calls show, with no level of its own: the checks above say how they rate.
    fn calls(&self) -> String {
        let matched = self
            .rating
            .reasons
            .iter()
            .filter(|reason| reason.rule == ADDED_CALL)
            .count();
        let unclassified: usize = self
            .changes
            .iter()
            .map(|change| change.calls_unclassified.len())
            .sum();
        let unresolved = self
            .changes
            .iter()
            .filter(|change| change.unresolved_calls)
            .count();
        if matched > 0 {
            return format!("👀 {} a rule names", plural(matched, "call", "calls"));
        }

        let unknown = nonzero(unresolved, "unknown target", "unknown targets")
            .map(|count| format!(", {count}"));
        match unclassified + unresolved {
            0 => "✅ nothing new to flag".to_owned(),
            _ => format!(
                "👀 {} nothing classifies{}",
                plural(unclassified, "new call", "new calls"),
                unknown.unwrap_or_default()
            ),
        }
    }

    fn effects(&self) -> String {
        let gained = effect_kinds(&self.changes, |change| &change.effects_gained);
        let lost = effect_kinds(&self.changes, |change| &change.effects_lost);
        let said: Vec<String> = [("gains", gained), ("loses", lost)]
            .into_iter()
            .filter(|(_, kinds)| !kinds.is_empty())
            .map(|(verb, kinds)| format!("{verb} {}", kinds.join(", ")))
            .collect();

        match said.is_empty() {
            true => "✅ unchanged".to_owned(),
            false => format!("👀 {}", said.join("; ")),
        }
    }

    fn coverage(&self) -> String {
        let count = |kind| {
            self.changes
                .iter()
                .filter(|change| change.kind == kind)
                .count()
        };
        let outside = nonzero(self.changed_outside_functions.len(), "file", "files")
            .map(|count| count + " changed outside a function");
        let gaps = [
            outside,
            nonzero(
                count(ChangeKind::TextOnly),
                "text-only function",
                "text-only functions",
            ),
            nonzero(
                count(ChangeKind::Unknown),
                "unknown function",
                "unknown functions",
            ),
            nonzero(self.tests_changed, "test function", "test functions")
                .map(|count| count + " not rated"),
            nonzero(
                self.not_compared,
                "generated function",
                "generated functions",
            )
            .map(|count| count + " not compared"),
        ];

        let gaps: Vec<String> = gaps.into_iter().flatten().collect();
        match gaps.is_empty() {
            true => "✅ no gaps".to_owned(),
            false => format!("👀 {}", gaps.join("; ")),
        }
    }

    /// Every changed function, in a table per file, then what no single function says.
    fn functions(&self, links: &Links) -> Option<String> {
        if self.changes.is_empty() {
            return None;
        }
        let tables = self
            .files()
            .into_iter()
            .map(|path| self.file_table(path, links));
        let rest = [self.unclassified_table(), self.outside(links)];

        let body: Vec<String> = tables.chain(rest.into_iter().flatten()).collect();
        let summary = format!(
            "<strong>{}</strong> in {}",
            plural(self.changes.len(), "function", "functions"),
            plural(self.files().len(), "file", "files")
        );
        Some(format!(
            "<details><summary>{summary}</summary>\n\n{}\n\n</details>",
            body.join("\n\n")
        ))
    }

    fn file_table(&self, path: &str, links: &Links) -> String {
        let mut changes: Vec<&FunctionChange> = self
            .changes
            .iter()
            .filter(|change| change.path == path)
            .collect();
        changes.sort_by_key(|change| change.line);
        let rows = changes.into_iter().map(|change| {
            let used = format!("{} ({} direct)", change.reached_by, change.callers);
            format!(
                "| {} | {} | {used} |",
                place(change, links),
                cell(&what_changed(change))
            )
        });

        let header = "| Function | What changed | Used by |\n|---|---|--:|";
        format!(
            "**{}**\n\n{header}\n{}",
            links.file(path),
            rows.collect::<Vec<_>>().join("\n")
        )
    }

    /// The library calls nothing classifies, by how often the change makes them.
    fn unclassified_table(&self) -> Option<String> {
        let calls = self
            .changes
            .iter()
            .flat_map(|change| change.calls_unclassified.iter());
        let counted = calls.fold(BTreeMap::<String, usize>::new(), |mut counts, callee| {
            *counts.entry(name(callee)).or_default() += 1;
            counts
        });
        let mut ranked: Vec<(String, usize)> = counted.into_iter().collect();
        ranked.sort_by(|(a, a_count), (b, b_count)| b_count.cmp(a_count).then(a.cmp(b)));
        if ranked.is_empty() {
            return None;
        }

        let rest = ranked.split_off(ranked.len().min(CALLS_SHOWN));
        let rows = ranked
            .into_iter()
            .map(|(callee, count)| format!("| {} | {count} |", cell(&code(&callee))));
        let more = (!rest.is_empty()).then(|| {
            let times: usize = rest.iter().map(|(_, count)| count).sum();
            format!("| …{} more | {times} |", rest.len())
        });
        let rows: Vec<String> = rows.chain(more).collect();
        Some(format!(
            "**Unclassified library calls**\n\n| Call | Times |\n|---|--:|\n{}",
            rows.join("\n")
        ))
    }

    fn outside(&self, links: &Links) -> Option<String> {
        if self.changed_outside_functions.is_empty() {
            return None;
        }
        let files: Vec<String> = self
            .changed_outside_functions
            .iter()
            .map(|path| links.file(path))
            .collect();
        Some(format!(
            "**Changed outside any function:** {}",
            files.join(", ")
        ))
    }
}

/// A check's line under the headline when it's above low: its strongest level and what it found
/// there, with the callees it names.
fn held(reasons: &[Reason], rule: &str, title: &str) -> Option<String> {
    let found: Vec<&Reason> = reasons
        .iter()
        .filter(|reason| reason.rule == rule)
        .collect();
    let level = found
        .iter()
        .map(|reason| reason.level)
        .reduce(Level::strongest)?;
    if level.weight() <= Level::Low.weight() {
        return None;
    }

    let at_level: Vec<&Reason> = found
        .into_iter()
        .filter(|reason| reason.level == level)
        .collect();
    let messages: BTreeSet<String> = at_level
        .iter()
        .map(|reason| without_callee(reason))
        .collect();
    let said = messages
        .into_iter()
        .map(|message| escape(&message))
        .collect::<Vec<_>>()
        .join("; ");
    let callees = named_callees(&at_level);
    Some(format!("- {} **{title}**: {said}{callees}.", icon(level)))
}

/// A reason's message without the callee it names, so reasons that differ only by callee read as
/// one.
fn without_callee(reason: &Reason) -> String {
    match reason.callee.as_deref() {
        Some(callee) => reason
            .message
            .replace(callee, "")
            .trim_end_matches([':', ' '])
            .to_owned(),
        None => reason.message.trim_end_matches('.').to_owned(),
    }
}

/// The callees a check's reasons name, the first few of them.
fn named_callees(reasons: &[&Reason]) -> String {
    let callees: BTreeSet<String> = reasons
        .iter()
        .filter_map(|reason| reason.callee.as_deref())
        .map(name)
        .collect();
    if callees.is_empty() {
        return String::new();
    }

    let shown: Vec<String> = callees
        .iter()
        .take(CALLEES_SHOWN)
        .map(|callee| code(callee))
        .collect();
    let more = callees.len().saturating_sub(CALLEES_SHOWN);
    let rest = (more > 0).then(|| format!(" and {more} more"));
    format!(": {}{}", shown.join(", "), rest.unwrap_or_default())
}

/// What changed in a function, in the order a reviewer weighs it.
fn what_changed(change: &FunctionChange) -> String {
    let flags = [
        change
            .signature_changed
            .then(|| "signature changed".to_owned()),
        change
            .values_changed
            .then(|| "a known value changed".to_owned()),
        change
            .unresolved_calls
            .then(|| "calls an unknown target".to_owned()),
        nonzero(
            change.calls_unclassified.len(),
            "unclassified call",
            "unclassified calls",
        ),
        effect_change("gains", &change.effects_gained),
        effect_change("loses", &change.effects_lost),
    ];
    // All of a new or removed function's calls are what it is, not what changed.
    let moved = !matches!(change.kind, ChangeKind::Added | ChangeKind::Removed);
    let new: Vec<&String> = change
        .calls_added
        .iter()
        .filter(|callee| !change.calls_unclassified.contains(callee))
        .collect();
    let calls = [
        moved.then(|| callees("now calls", new)).flatten(),
        moved
            .then(|| callees("no longer calls", change.calls_removed.iter().collect()))
            .flatten(),
    ];

    std::iter::once(change.kind.name().to_owned())
        .chain(flags.into_iter().flatten())
        .chain(calls.into_iter().flatten())
        .collect::<Vec<_>>()
        .join("; ")
}

fn effect_change(verb: &str, effects: &[EffectChange]) -> Option<String> {
    let kinds: BTreeSet<&str> = effects.iter().map(|effect| effect.kind).collect();
    let kinds: Vec<&str> = kinds.into_iter().collect();
    (!kinds.is_empty()).then(|| format!("{verb} {}", kinds.join(", ")))
}

fn callees(label: &str, callees: Vec<&String>) -> Option<String> {
    if callees.is_empty() {
        return None;
    }
    let names: Vec<String> = callees
        .into_iter()
        .map(|callee| code(&name(callee)))
        .collect();
    Some(format!("{label} {}", names.join(", ")))
}

/// The kinds of effect the changes gained, or lost, in order.
fn effect_kinds(
    changes: &[FunctionChange],
    pick: fn(&FunctionChange) -> &[EffectChange],
) -> Vec<&'static str> {
    let kinds: BTreeSet<&'static str> = changes
        .iter()
        .flat_map(|change| pick(change).iter().map(|effect| effect.kind))
        .collect();
    kinds.into_iter().collect()
}

/// A function's name, linked to its line on the appropriate side of the PR diff.
fn place(change: &FunctionChange, links: &Links) -> String {
    let named = cell(&code(&name(&change.name)));
    let side = match change.kind {
        ChangeKind::Removed => 'L',
        _ => 'R',
    };
    let line = (change.line > 0).then_some((side, change.line));
    links.to(named, &change.path, line)
}

/// How many functions of each kind, kinds with none left out.
fn tally(changes: &[FunctionChange]) -> String {
    let count = |kind| changes.iter().filter(|change| change.kind == kind).count();
    let said = KINDS
        .into_iter()
        .filter_map(|kind| nonzero(count(kind), kind.name(), kind.name()));
    said.collect::<Vec<_>>().join(", ")
}

/// The headline's mark: a color for a measured level, eyes for what needs a person.
fn icon(level: Level) -> &'static str {
    match level {
        Level::Low => "🟢",
        Level::Medium => "🟡",
        Level::High => "🔴",
        Level::Unknown => "👀",
        Level::Unrated => "⚪",
    }
}

fn plural(count: usize, one: &str, many: &str) -> String {
    let noun = if count == 1 { one } else { many };
    format!("{count} {noun}")
}

fn nonzero(count: usize, one: &str, many: &str) -> Option<String> {
    (count > 0).then(|| plural(count, one, many))
}

/// A function or callee without the module path or language prefix around it: a Rust method keeps
/// its type, as `Links::to` for `markdown::Links::<'_>::to`, `ChangeReport::markdown` for
/// `markdown::<impl merge_risk::ChangeReport>::markdown` and `slice::join` for
/// `alloc::slice::{impl#0}::join`. A Go identity drops its import path's directories, as
/// `native.load` for `go::github.com/o/r/native.load`. A C++ identity is read by [`cxx_name`].
fn name(identity: &str) -> String {
    if let Some(path) = cxx_path(identity) {
        return cxx_name(&path);
    }
    if let Some((owner, item)) = impl_item(identity) {
        return format!("{owner}::{item}");
    }
    let raw: Vec<&str> = identity.split("::").collect();
    if let [.., owner, block, item] = raw.as_slice()
        && block.starts_with("{impl")
    {
        return format!("{owner}::{item}");
    }

    let parts: Vec<&str> = raw
        .into_iter()
        .filter(|part| !part.starts_with(['<', '{']))
        .collect();
    match parts.as_slice() {
        [.., owner, item] if owner.starts_with(char::is_uppercase) => format!("{owner}::{item}"),
        _ => short(parts.last().copied().unwrap_or(identity)),
    }
}

/// A C++ callee's scopes and name, without what its signature adds: its template arguments,
/// parameters, qualifiers and return type, any of which can hold a `::` of its own.
/// `cxx::std::get_if<typename>(variant<…> *) -> typename add_pointer<…>::type` is `std::get_if`.
fn cxx_path(identity: &str) -> Option<String> {
    let signature = identity.strip_prefix("cxx::")?;
    let mut angles = 0_usize;
    let mut path = String::with_capacity(signature.len());
    for character in signature.chars() {
        match character {
            '<' => angles += 1,
            '>' => angles = angles.saturating_sub(1),
            // A scope such as `(anonymous namespace)` starts with one, and parameters follow a name.
            '(' if angles == 0 && !path.is_empty() && !path.ends_with("::") => break,
            _ if angles == 0 => path.push(character),
            _ => {}
        }
    }
    Some(path)
}

/// A C++ name with the scope it's in, since a type in C++ is as often lowercase as not and a
/// namespace tells `fs::remove` from `filesystem::remove`. A file or an anonymous namespace says
/// nothing a reader can use, so a name in one stands alone.
fn cxx_name(path: &str) -> String {
    let mut parts = path.rsplit("::");
    let item = parts.next().unwrap_or(path);
    match parts.next() {
        Some(scope) if !scope.starts_with('(') && !scope.contains(['/', '.']) => {
            format!("{scope}::{item}")
        }
        _ => item.to_owned(),
    }
}

/// The type and item of `…<impl path::Type>::item`.
fn impl_item(name: &str) -> Option<(&str, &str)> {
    let (_, rest) = name.rsplit_once("<impl ")?;
    let (owner, item) = rest.split_once(">::")?;
    Some((owner.rsplit("::").next().unwrap_or(owner), item))
}

/// A name without the directories of its import path: `github.com/o/r/native.f` reads as
/// `native.f`, and `(io/fs.FileInfo).Size` as `(fs.FileInfo).Size`.
fn short(identity: &str) -> String {
    let mut shortened = String::with_capacity(identity.len());
    let mut segment = String::new();
    for character in identity.chars() {
        match character {
            '/' => segment.clear(),
            'A'..='Z' | 'a'..='z' | '0'..='9' | '.' | '-' | '_' | '~' => segment.push(character),
            _ => {
                shortened.push_str(&segment);
                segment.clear();
                shortened.push(character);
            }
        }
    }

    shortened.push_str(&segment);
    shortened
}

/// Where the report links a file to, if anywhere.
struct Links<'a>(Option<&'a str>);

impl Links<'_> {
    /// `text` as a link to a line of a file, or as it is.
    fn to(&self, text: String, path: &str, line: Option<(char, usize)>) -> String {
        let Some(root) = self.0 else {
            return text;
        };
        // GitHub diff anchors hash the exact repository-relative UTF-8 path, not a URL-encoded path.
        let digest = Sha256::digest(path.as_bytes());
        let anchor = line
            .map(|(side, line)| format!("{side}{line}"))
            .unwrap_or_default();
        format!("[{text}]({root}/files#diff-{digest:x}{anchor})")
    }

    fn file(&self, path: &str) -> String {
        self.to(code(path), path, None)
    }
}

/// A code span. It only holds identifiers and paths, which hold no backtick.
fn code(text: &str) -> String {
    format!("`{text}`")
}

/// Text for a table cell, where a bare `|` would end the cell.
fn cell(text: &str) -> String {
    text.replace('|', "\\|")
}

/// Text with what Markdown would read as syntax escaped.
fn escape(text: &str) -> String {
    let mut escaped = String::with_capacity(text.len());
    for character in text.chars() {
        if "\\`*_[]<>#|~".contains(character) {
            escaped.push('\\');
        }
        escaped.push(character);
    }
    escaped
}

